const API_URL = 'http://127.0.0.1:8000';
const EffortLevels = ['low', 'medium', 'high', 'xhigh'];
const DemoAgents = [
  {id:'director',name:'DIRECTOR',role:'Dirección',tone:'#ffd166',hue:'-100deg',tokens_used:1260,token_budget:6000,reasoning_effort:'high',status:'sleeping',idle_mode:'Coffee',sleep:[13,33],work:[29,20],action:'priorizando'},
  {id:'nexus',name:'NEXUS',role:'Coordinación',tone:'#d9f45a',hue:'68deg',tokens_used:2870,token_budget:8000,reasoning_effort:'high',status:'sleeping',idle_mode:'Eating',sleep:[84,42],work:[47,21],action:'planificando'},
  {id:'scout',name:'SCOUT',role:'Investigación',tone:'#79e8ee',hue:'0deg',tokens_used:1920,token_budget:5500,reasoning_effort:'medium',status:'sleeping',idle_mode:'Sleep',sleep:[20,75],work:[66,22],action:'investigando'},
  {id:'forge',name:'FORGE',role:'Construcción',tone:'#ff789d',hue:'135deg',tokens_used:840,token_budget:7000,reasoning_effort:'medium',status:'sleeping',idle_mode:'Sleep',sleep:[35,75],work:[31,42],action:'construyendo'},
  {id:'sentinel',name:'SENTINEL',role:'Calidad',tone:'#ab8cff',hue:'230deg',tokens_used:610,token_budget:4500,reasoning_effort:'low',status:'sleeping',idle_mode:'Coffee',sleep:[14,42],work:[57,42],action:'revisando'}
];
const State = { agents: structuredClone(DemoAgents), events: [], selectedAgentId: 'nexus', connected: false, lastTelemetryAt: null };
const $ = (selector) => document.querySelector(selector);
const formatNumber = (value) => new Intl.NumberFormat('es-ES').format(value);
const uppercase = (value) => value.toUpperCase();
const getSelectedAgent = () => State.agents.find((agent) => agent.id === State.selectedAgentId);
const fetchApi = async (path, options = {}) => { const response = await fetch(API_URL + path, {headers:{'Content-Type':'application/json'}, ...options}); if (!response.ok) throw new Error('API unavailable'); return response.json(); };

function renderControlPanel() { const agent = getSelectedAgent(); $('#agentSelect').innerHTML = State.agents.map((item) => `<option value="${item.id}">${item.name} — ${item.role}</option>`).join(''); $('#agentSelect').value = agent.id; $('#budgetInput').value = agent.token_budget; $('#effortSelector').innerHTML = EffortLevels.map((level) => `<button class="EffortButton ${agent.reasoning_effort === level ? 'Active' : ''}" data-effort="${level}">${uppercase(level)}</button>`).join(''); }
function renderMetricsPanel() { const used = State.agents.reduce((sum, agent) => sum + agent.tokens_used, 0); const budget = State.agents.reduce((sum, agent) => sum + agent.token_budget, 0); const active = State.agents.filter((agent) => agent.status === 'working').length; const usage = Math.min(100, Math.round((used / budget) * 100)); const margin = 100 - usage; const health = usage < 65 ? 'EFICIENTE' : usage < 85 ? 'VIGILAR' : 'REVISAR'; $('#budgetUsage').textContent = `${usage}%`; $('#budgetMargin').textContent = `${margin}%`; $('#activeAgents').textContent = `${active}/5`; $('#budgetHealth').textContent = health; $('#budgetBar').style.width = `${usage}%`; $('#budgetNumbers').textContent = `${formatNumber(used)} / ${formatNumber(budget)} tokens`; $('#efficiencyMessage').textContent = usage < 65 ? 'Gasto bajo control' : usage < 85 ? 'Prioriza tareas complejas' : 'Ajusta límites'; $('#telemetryStamp').textContent = State.lastTelemetryAt ? `Actualizado ${State.lastTelemetryAt.toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit', second:'2-digit'})} · ${State.connected ? 'API en directo' : 'modo simulación'}` : 'Esperando telemetría'; }
function renderActivityLog() { $('#activityLog').innerHTML = State.events.slice(0,4).map((event) => `<article class="ActivityItem"><time>${new Date(event.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</time><div><b>${event.agent}</b><br><span>${event.message}</span></div></article>`).join('') || '<div class="ActivityItem"><time>—</time><span>Sin actividad aún.</span></div>'; }
function createSlimeUnit(agent) { const [x, y] = agent.status === 'working' ? agent.work : agent.sleep; const stateClass = agent.status === 'working' ? 'Working' : `Resting ${agent.idle_mode}`; return `<div class="SlimeUnit ${stateClass}" style="--tone:${agent.tone};--hue:${agent.hue || '0deg'};--x:${x}%;--y:${y}%"><i class="WorkLabel">${agent.action}</i><i class="IdleProp"></i><i class="SlimeSprite" aria-hidden="true"></i><strong>${agent.name}</strong></div>`; }
function renderSlimeRoom() { const room = $('#slimeRoom'); room.querySelectorAll('.SlimeUnit').forEach((element) => element.remove()); room.insertAdjacentHTML('beforeend', State.agents.map(createSlimeUnit).join('')); const activeNames = State.agents.filter((agent) => agent.status === 'working').map((agent) => agent.name); $('#roomStatus').textContent = activeNames.length ? activeNames.join(' + ') : 'Todos descansando'; }
function renderDashboard() { renderControlPanel(); renderMetricsPanel(); renderActivityLog(); renderSlimeRoom(); }
function updateConnectionLabel() { $('#apiStatus').textContent = State.connected ? '● API CONECTADA' : '● API DEMO'; $('#apiStatus').style.color = State.connected ? 'var(--acid)' : 'var(--cyan)'; }
function updateDigitalClock() { const now = new Date(); $('#digitalTime').textContent = now.toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false}); const date = new Intl.DateTimeFormat('es-ES', {weekday:'long', day:'2-digit', month:'short', year:'numeric'}).format(now).replace('.', '').toUpperCase(); $('#digitalDate').textContent = date.replace(',', ' ·'); }
async function syncDashboard() { const dashboard = await fetchApi('/api/dashboard'); dashboard.agents.forEach((remoteAgent) => { const localAgent = State.agents.find((agent) => agent.id === remoteAgent.id); if (localAgent) Object.assign(localAgent, remoteAgent, {status: remoteAgent.status === 'running' ? 'working' : 'sleeping'}); }); State.events = dashboard.events || []; State.connected = true; State.lastTelemetryAt = new Date(); updateConnectionLabel(); renderDashboard(); }
function runLocalTelemetry() { if (State.connected) return; let changed = false; State.agents.forEach((agent) => { if (agent.status !== 'working') return; const rates = {low: 2, medium: 4, high: 7, xhigh: 11}; agent.tokens_used = Math.min(agent.token_budget, agent.tokens_used + rates[agent.reasoning_effort]); if (agent.tokens_used >= agent.token_budget) agent.status = 'sleeping'; changed = true; }); if (changed) { State.lastTelemetryAt = new Date(); renderMetricsPanel(); } }
function localRouteMission(prompt) { const value = prompt.toLowerCase(); const selected = ['director','nexus']; if (/investiga|fuente|busca|compet|analiza/.test(value)) selected.push('scout'); if (/crea|constru|código|codigo|web|diseña|disena/.test(value)) selected.push('forge'); if (/revisa|calidad|error|test|riesgo/.test(value)) selected.push('sentinel'); return [...new Set(selected.length === 2 ? [...selected, 'scout'] : selected)]; }
async function submitMission(event) { event.preventDefault(); const input = $('#missionInput'); const prompt = input.value.trim(); if (!prompt) return; let assigned = localRouteMission(prompt); let summary = 'Misión asignada en modo demo.'; try { const result = await fetchApi('/api/dispatch', {method:'POST', body:JSON.stringify({prompt})}); assigned = result.agent_ids; summary = result.plan; } catch {} State.agents.forEach((agent) => { agent.status = assigned.includes(agent.id) ? 'working' : 'sleeping'; }); $('#missionSummary').textContent = summary; input.value = ''; renderDashboard(); try { await syncDashboard(); } catch {} }
async function saveAgentControls() { const agent = getSelectedAgent(); agent.token_budget = Number($('#budgetInput').value); try { const updated = await fetchApi(`/api/agents/${agent.id}/controls`, {method:'POST', body:JSON.stringify({token_budget:agent.token_budget,reasoning_effort:agent.reasoning_effort})}); Object.assign(agent, updated); } catch {} renderDashboard(); }
function bindInteractions() { $('#agentSelect').addEventListener('change', (event) => { State.selectedAgentId = event.target.value; renderControlPanel(); }); $('#effortSelector').addEventListener('click', (event) => { const level = event.target.dataset.effort; if (!level) return; getSelectedAgent().reasoning_effort = level; renderControlPanel(); }); $('#saveControls').addEventListener('click', saveAgentControls); $('#missionForm').addEventListener('submit', submitMission); }
bindInteractions(); renderDashboard(); updateDigitalClock(); syncDashboard().catch(() => { updateConnectionLabel(); }); setInterval(() => syncDashboard().catch(() => {}), 2000); setInterval(runLocalTelemetry, 1000); setInterval(updateDigitalClock, 1000);
